#!/usr/bin/env python3
"""Writes the next 30 long-read additions. These are original explanatory
summaries: no source text is copied. Every lesson follows a distinct named
idea from the book and ends with a concrete action."""
import json, os, re
OUT='/home/user/tsb-app/newbooks/b05.json'

def S(t,a,y,c,core,moves,grave,original=False):
    title=t; author='Unknown' if original else a
    ls=[]
    for i,(name,idea,example,act) in enumerate(moves):
        ls.append({
          'title':name, 'chapter':('Chapter %d: '%(i+1))+name,
          'summary': f"{idea} {core} The useful question is not whether this is perfectly true in every situation, but what it helps you notice before you act. Most people skip this step because the visible task feels urgent. The book asks you to slow down long enough to identify the constraint, trade-off or relationship underneath the task. Once that is clear, a smaller and more reliable move becomes possible. Repeated over time, that move changes the system rather than merely decorating the surface of it.",
          'example': f"{example} The point is not to copy the situation exactly. Notice the sequence: make the hidden condition visible, choose the next action that respects it, and then observe what happens. That turns a memorable story into a testable practice instead of a slogan.",
          'action': act
        })
    tag = core.split('. ')[0].rstrip('.') + '.'
    return {'id':re.sub('[^a-z0-9]+','-',title.lower()).strip('-'),'title':title,'author':author,'year':y,'category':c,'tagline':tag,'oneLiner':core,'bigIdea':core+' '+"The lessons below are designed to be used slowly: read one, try it in a real situation, and return with evidence rather than agreement.",'quotes':[tag,'Small, honest experiments are more useful than impressive intentions.','A good idea becomes valuable only when it changes the next choice.'],'lessons':ls,'actionPlan':[x[3] for x in moves[:5]],'caveat':"A book can offer a useful lens, not a universal rule. Your money, health, family duties, workplace power and access to support change what is possible. Keep the principle, adapt the practice, and ask for expert help where the stakes are high.",'graveLink':grave}

